"""Serum 2's state inside an FL channel (src/coproducer/serumstate.py), read from a channel FL 26.1.7 saved with the serum-mcp preset
"CP - Deep Sub" loaded (sandbox\\serum\\serum_sounds.flp, 2026-10-26). Both presets here were generated by serum-mcp for this project."""
import hashlib
import json
import struct

import pytest

from coproducer import serumstate as ss

DATA = "tests/data/"


def _blob():
    return open(DATA + "serum2_channel_deep_sub.bin", "rb").read()


def test_the_channel_state_reads_as_two_xfer_containers():
    b = _blob()
    assert ss.is_serum2(b) and not ss.is_serum2(b"\x00" * 40) and ss.preset_name(b) == "CP - Deep Sub"
    st = ss.read_state(b)
    assert [r for r, _ in st["records"]] == [1, 3, 2, 4]
    (pm, pd), (cm, cd) = st["processor"], st["controller"]
    assert pm["component"] == "processor" and cm["component"] == "controller" and cd["presetName"] == "CP - Deep Sub"
    rec = dict(st["records"])[ss.REC_PROCESSOR]
    n = struct.unpack_from("<Q", rec, 9)[0]
    z = rec[9 + 8 + n + 8:]
    assert pm["hash"] == hashlib.md5(z).hexdigest()                    # the JSON hash is the MD5 of the zstd frame
    assert "ModSlot63" in pd and "SerumGUI" in cd and "SerumGUI" not in pd


def test_rebuilding_with_the_same_values_keeps_every_other_byte():
    b = _blob()
    st = ss.read_state(b)
    again = ss.build_blob(b, st["processor"], st["controller"])
    back = ss.read_state(again)
    assert back["processor"][1] == st["processor"][1] and back["controller"][1] == st["controller"][1]
    keep = {cid: d for cid, d in st["chunks"] if cid != ss.PLUGIN_STATE_CHUNK}
    assert {cid: d for cid, d in back["chunks"] if cid != ss.PLUGIN_STATE_CHUNK} == keep
    assert dict(back["records"])[1] == dict(st["records"])[1] and dict(back["records"])[4] == dict(st["records"])[4]


def test_a_preset_splits_the_way_serum_split_it():
    """The same preset put back on its own channel: the engine half matches what Serum wrote, apart from fields Serum fills in itself."""
    b = _blob()
    native = ss.read_state(b)
    ours = ss.read_state(ss.inject_preset(b, open(DATA + "cp_deep_sub.SerumPreset", "rb").read(), "x"))
    p_ours, p_native = ours["processor"][1], native["processor"][1]
    assert set(p_ours) == set(p_native)
    assert p_ours["Env0"]["plainParams"]["kParamDecay"] == pytest.approx(p_native["Env0"]["plainParams"]["kParamDecay"])
    assert p_ours["ModSlot0"] == p_native["ModSlot0"] and p_ours["ModSlot5"] == {"plainParams": {}}
    assert p_ours["RoutingSlot0"] == {"plainParams": {}}                # 'default' written the way Serum writes it
    c_ours = ours["controller"][1]
    assert c_ours["Macro0"] == {"name": "DRIVE"} and "plainParams" not in json.dumps(c_ours["FXRack0"])
    assert c_ours["product"] == "Serum2" and c_ours["selectedPresetPath"] == "x"


def test_another_preset_goes_on_the_channel():
    b = _blob()
    new = ss.inject_preset(b, open(DATA + "cp_house_stab.SerumPreset", "rb").read(), r"C:\\presets\\sandbox\\CP - House Stab.SerumPreset")
    st = ss.read_state(new)
    assert ss.preset_name(new) == "CP - House Stab" and st["controller"][0]["presetName"] == "CP - House Stab"
    env = st["processor"][1]["Env0"]["plainParams"]
    assert env["kParamDecay"] == 0.42 and env["kParamSustain"] == 0.22
    with pytest.raises(ss.SerumStateError):
        ss.inject_preset(b"\x0c\x00\x00\x00", b"XferJson\x00", "")


def test_the_builder_puts_a_generated_sound_on_a_serum_channel(tmp_path):
    from coproducer import remixbuild, testflp
    f = testflp.project({0: "Kick", 1: "Sub"}, {0: [0]}, presets={1: "x"})
    f.set_plugin_state(1, _blob())
    gen = tmp_path / "stab.serumstate"
    gen.write_bytes(ss.inject_preset(_blob(), open(DATA + "cp_house_stab.SerumPreset", "rb").read(), "x"))
    chans, blobs = remixbuild.serum_channels(f, {"sub": "CP - Deep Sub", "stab": "PL Crusty Pluck [LCV]"}, {"stab": str(gen)}, log=lambda *a: None)
    assert chans == {"sub": 1, "stab": 1} and ss.preset_name(blobs["stab"]) == "CP - House Stab"   # the stab rides on a Serum 2 carrier
    f.set_plugin_state(1, blobs["stab"])
    assert f.plugin_preset_name(1) == "CP - House Stab"
    bad = tmp_path / "bad.serumstate"
    bad.write_bytes(b"\x0c\x00\x00\x00")
    with pytest.raises(remixbuild.BuildError):
        remixbuild.serum_channels(f, {}, {"arp": str(bad)}, log=lambda *a: None)


def test_juce_states_round_trip():
    """pedalboard's raw_state for Serum 2: the known start of the default state's IComponent text (read on the host, 2026-10-26)."""
    assert ss.juce_b64_encode(b"XferJson\x00\xb7\x00\x00\x00\x00\x00\x00\x00").split(".", 1)[1].startswith("XYVYxozbu4F.2B")
    proc, ctl = ss.components(_blob())
    raw = ss.juce_state(proc, ctl)
    assert raw[:4] == b"VC2!" and struct.unpack_from("<I", raw, 4)[0] == len(raw) - 9 and raw.endswith(b"</VST3PluginState>\x00")
    assert ss.parse_juce_state(raw) == (proc, ctl)
    assert ss.from_components(_blob(), proc, ctl) == _blob()
